"""Generate a dependency-free local trace viewer."""
import json
from html import escape

def render_viewer(trace, summary):
    spans=trace['spans'];starts=[span.get('start_ms',0) for span in spans];ends=[start+span['duration_ms'] for start,span in zip(starts,spans)];origin=min(starts,default=0);extent=max(ends,default=1)-origin or 1
    rows=[]
    for span,start in zip(spans,starts):
        left=(start-origin)/extent*100;width=max(span['duration_ms']/extent*100,.35);status=escape(span['status']);tool=escape(span['tool']);identifier=escape(span['id'])
        rows.append(f'<li data-status="{status}"><button class="span" style="--left:{left:.3f}%;--width:{width:.3f}%" aria-label="{tool}, {span["duration_ms"]} milliseconds, {status}"><b>{tool}</b><small>{identifier} · {span["duration_ms"]} ms · {status}</small><i></i></button></li>')
    errors=sum(span['status']=='error' for span in spans)
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Agent Flight Recorder</title><style>{STYLE}</style></head><body><a class="skip" href="#timeline">Skip to timeline</a><header><span>AFR / LOCAL TRACE</span><strong>Agent Flight Recorder</strong><em>OFFLINE REPORT</em></header><main><section class="hero"><p>TRACE CONTROL / READ-ONLY</p><h1>Every tool call.<br><i>One clear flight path.</i></h1></section><section class="metrics"><article><b>{len(spans)}</b><span>SPANS</span></article><article><b>{errors}</b><span>FAILURES</span></article><article><b>{summary['tokens']}</b><span>REPORTED TOKENS</span></article><article><b>{summary['summed_duration_ms']:g}</b><span>SUMMED MS</span></article></section><section class="controls" aria-label="Timeline filters"><button class="active" data-filter="all">All spans</button><button data-filter="error">Failures only</button></section><section id="timeline"><div class="scale"><span>START</span><span>TRACE WINDOW</span><span>END</span></div><ol>{''.join(rows)}</ol><p id="empty" hidden>No failed spans in this trace.</p></section><p class="note">Timeline positions use supplied start_ms offsets when available; otherwise spans share the same origin. Durations may overlap and parent spans may include child work.</p></main><script>{SCRIPT}</script></body></html>'''

STYLE='''*:before,*:after,*{box-sizing:border-box}:root{color-scheme:dark;--bg:#090b13;--panel:#111522;--line:#293049;--ink:#f4f1ea;--muted:#979fb5;--cyan:#6de8f0;--red:#ff6d78}body{margin:0;background:radial-gradient(circle at 80% 0,#182440 0,transparent 38%),var(--bg);color:var(--ink);font:15px/1.5 system-ui,sans-serif}header,main{max-width:1300px;margin:auto}header{padding:24px 5vw;border-bottom:1px solid var(--line);display:flex;align-items:center;gap:24px}header span,header em,.hero p{font:10px ui-monospace,monospace;letter-spacing:2px;color:var(--cyan)}header strong{font-size:18px}header em{margin-left:auto;color:var(--muted);font-style:normal}main{padding:55px 5vw 80px}.hero h1{font-size:clamp(44px,7vw,88px);line-height:1;letter-spacing:-.06em;margin:15px 0 40px}.hero h1 i{font-style:normal;color:var(--cyan)}.metrics{display:grid;grid-template-columns:repeat(4,1fr);border:1px solid var(--line);border-radius:14px;overflow:hidden}.metrics article{padding:20px;border-right:1px solid var(--line);background:#111522cc}.metrics article:last-child{border:0}.metrics b{display:block;font:36px ui-monospace,monospace}.metrics span{color:var(--muted);font:10px ui-monospace,monospace;letter-spacing:1px}.controls{display:flex;gap:10px;margin:35px 0 15px}.controls button{background:transparent;color:var(--ink);border:1px solid var(--line);padding:9px 14px;border-radius:99px;cursor:pointer}.controls button.active{background:var(--cyan);color:#061318;border-color:var(--cyan)}button:focus-visible,.span:focus-visible{outline:3px solid var(--cyan);outline-offset:3px}#timeline{padding:20px;background:var(--panel);border:1px solid var(--line);border-radius:14px}.scale{display:flex;justify-content:space-between;color:var(--muted);font:9px ui-monospace,monospace;letter-spacing:1px;border-bottom:1px solid var(--line);padding-bottom:10px}ol{list-style:none;padding:12px 0 0;margin:0}li{position:relative;height:62px;border-bottom:1px solid #1e2538}.span{position:absolute;left:var(--left);width:var(--width);min-width:150px;max-width:calc(100% - var(--left));height:48px;overflow:hidden;text-align:left;background:#17283a;color:var(--ink);border:1px solid #315169;border-radius:7px;padding:7px 10px;cursor:default}.span b,.span small{display:block;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.span small{color:var(--muted)}li[data-status=error] .span{border-color:var(--red);background:#321c29}.note,#empty{color:var(--muted)}.skip{position:absolute;top:-100px;left:10px;background:var(--cyan);color:#000;padding:8px}.skip:focus{top:10px}@media(max-width:680px){.metrics{grid-template-columns:1fr 1fr}.metrics article:nth-child(2){border-right:0}.metrics article{border-bottom:1px solid var(--line)}header span{display:none}.hero h1{font-size:46px}.span{min-width:min(125px,calc(100% - var(--left)))}}@media(prefers-reduced-motion:reduce){*{scroll-behavior:auto!important}}'''
SCRIPT='''const buttons=document.querySelectorAll('[data-filter]'),rows=[...document.querySelectorAll('#timeline li')],empty=document.querySelector('#empty');for(const button of buttons)button.onclick=()=>{for(const item of buttons)item.classList.toggle('active',item===button);let visible=0;for(const row of rows){const show=button.dataset.filter==='all'||row.dataset.status===button.dataset.filter;row.hidden=!show;visible+=show}empty.hidden=visible>0};'''
